import { Injectable } from '@angular/core';
import { SemiFinished } from '../pages/semi-finished/semi-finished';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
export interface FinishedProductInward {
  productId:  number
  productName: string, 
  lotNo: string,
  bags: number,
  perKg: number,
  grossQty: number,
  semiFinishedId: number, 
  inwardDate: string,
}

export interface CreateFinishedProductInwardDto {
  productId: number;
  lotNo: string;
  bags: number;
  perKg: number;
  grossQty: number;
  semiFinishedId: number;
  inwardDate: string;
}

export interface SFOutwardDto {
  semiFinishedId: number;
  semiFinishedName: string;
  bags: number;
  kgBags: number;
  grossQty: number;
}

export interface UpdateFinishedProductInwardDto extends CreateFinishedProductInwardDto {
  id: number;
}
export interface CreateFinishedProductInwardRequest {
  Inward: CreateFinishedProductInwardDto;
  SFOutward: SFOutwardDto[];
}


@Injectable({
  providedIn: 'root'
})
export class FinishedProductInwardService {
   private apiUrl = `${environment.apiUrl}/finishedproductinward`; 
  constructor(private http: HttpClient) {}

  getInward(): Observable<FinishedProductInward[]> {
    return this.http.get<FinishedProductInward[]>(this.apiUrl);
  }
  getInwardByID(id: number): Observable<FinishedProductInward> {
    return this.http.get<FinishedProductInward>(`${this.apiUrl}/${id}`)
  }
  addInward(product: FinishedProductInward): Observable<FinishedProductInward> {
  return this.http.post<FinishedProductInward>(`${this.apiUrl}/create`, product);
}

updateInward(id: number, product: FinishedProductInward): Observable<FinishedProductInward> {
  return this.http.put<FinishedProductInward>(`${this.apiUrl}/update/${id}`, product);
}

deleteInward(id: number): Observable<void> {
  
  return this.http.delete<void>(`${this.apiUrl}/${id}`);
}
}
